function Stat({label,value,sub,tone="blue"}:{label:string;value:string|number;sub:string;tone?:"blue"|"green"|"amber"|"rose"}){
 const tones={blue:"from-blue-500/10 to-blue-50",green:"from-emerald-500/10 to-emerald-50",amber:"from-amber-500/10 to-amber-50",rose:"from-rose-500/10 to-rose-50"};
 return <Card className="overflow-hidden"><CardContent className={cn("bg-gradient-to-br p-5",tones[tone])}><p className="text-[11px] font-black uppercase tracking-[.12em] text-slate-500">{label}</p><div className="mt-2 text-3xl font-black tracking-tight text-slate-900">{value}</div><p className="mt-1 text-xs text-slate-500">{sub}</p></CardContent></Card>
}





function Metric({label,value,hint}:{label:string;value:string|number;hint:string}){
 return <Stat label={label} value={value} sub={hint}/>
}

function fmt(value?:string|null){return fmtDate(value)}
function mins(value?:number|null){return value==null?"—":`${Math.round(value/60000)} dk`}
function bytes(value?:number|null){
 if(value==null)return "—";
 const units=["B","KB","MB","GB","TB"];let n=Math.max(0,value),i=0;
 while(n>=1024&&i<units.length-1){n/=1024;i++}
 return `${n>=100||i===0?Math.round(n):n.toFixed(1)} ${units[i]}`;
}

