 return <><PageHero eyebrow="Security Center" title="Güvenlik & Acil Erişim" desc="Endpoint koruması, yönetim API tokenları ve break-glass recovery kodlarını tek merkezden yönetin." icon={ShieldCheck}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Toplam Agent" value={agents.length} sub="Koruma kapsamındaki filo"/><Stat label="Kilitli Agent" value={locked.length} sub="Müdahale gerektiren" tone={locked.length?"rose":"green"}/><Stat label="API Token" value={tokens.filter(t=>!t.revoked).length} sub="Aktif token"/><Stat label="Admin Hesabı" value={users.filter(u=>u.roles.includes("administrator")).length} sub="Break-glass adayı"/></div><div className="mt-6 grid gap-6 xl:grid-cols-2"><Card><CardHeader><div><CardTitle>Management API Token</CardTitle><CardDescription>Kısa ömürlü, rol sınırlı automation tokenı oluşturun.</CardDescription></div></CardHeader><CardContent className="space-y-3"><Input value={tokenName} onChange={e=>setTokenName(e.target.value)}/><Input type="number" min={1} value={validHours} onChange={e=>setValidHours(Number(e.target.value))}/><div className="flex flex-wrap gap-2">{roles.map(r=><label key={r} className="flex items-center gap-2 rounded-xl border px-3 py-2 text-xs"><input type="checkbox" checked={tokenRoles.includes(r)} onChange={e=>setTokenRoles(x=>e.target.checked?[...x,r]:x.filter(v=>v!==r))}/>{r}</label>)}</div><Button onClick={()=>void createToken()}>Token Oluştur</Button>{issued&&<div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs"><b className="block">Bir kez gösterilen token</b><code className="mt-2 block break-all select-all">{issued}</code></div>}{tokens.map(t=><div key={t.tokenId} className="flex items-center justify-between rounded-xl border p-3"><div><b className="text-xs">{t.name}</b><small className="block text-[10px] text-slate-400">{fmtDate(t.expiresAtUtc)}</small></div>{!t.revoked&&<Button size="sm" variant="danger" onClick={()=>void revoke(t)}>İptal</Button>}</div>)}</CardContent></Card><Card><CardHeader><div><CardTitle>Break-Glass Recovery</CardTitle><CardDescription>Administrator hesapları için acil erişim kodları.</CardDescription></div></CardHeader><CardContent className="space-y-3">{users.filter(u=>u.roles.includes("administrator")).map(u=><div key={u.userId} className="flex items-center justify-between rounded-xl border p-3"><div><b className="text-xs">{u.displayName||u.username}</b><small className="block text-[10px] text-slate-400">@{u.username}</small></div><Button size="sm" variant="outline" onClick={()=>void breakGlass(u.userId)}>Kodları Yenile</Button></div>)}{breakCodes.length>0&&<div className="rounded-xl border border-rose-200 bg-rose-50 p-4"><div className="grid grid-cols-2 gap-2">{breakCodes.map(c=><code key={c} className="rounded-lg bg-white p-2 text-center text-xs">{c}</code>)}</div></div>}{status&&<div className="rounded-xl bg-slate-50 p-3 text-xs">{status}</div>}</CardContent></Card></div></>
